const char* ImGui::GetVersion() {
    u64 capacity = 256;
    char* buffer = Imgui::Scratch_Text(capacity);
    u64 length = ImGui_GetVersion(buffer, capacity);

    if (length >= capacity) {
        capacity = length + 1;
        buffer = Imgui::Scratch_Text(capacity);
        ImGui_GetVersion(buffer, capacity);
    }
    return buffer;
}

