const char* ImGui::GetClipboardText() {
    u64 capacity = 256;
    char* buffer = Imgui::Scratch_Text(capacity);
    u64 length = ImGui_GetClipboardText(buffer, capacity);

    if (length >= capacity) {
        capacity = length + 1;
        buffer = Imgui::Scratch_Text(capacity);
        ImGui_GetClipboardText(buffer, capacity);
    }
    return buffer;
}

